Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: rtnetlink: zero ifla_vf_broadcast to avoid stack
 infoleak in rtnl_fill_vfinfo

rtnl_fill_vfinfo() declares struct ifla_vf_broadcast on the stack
without initialisation:

	struct ifla_vf_broadcast vf_broadcast;

The struct contains a single fixed 32-byte field:

	/* include/uapi/linux/if_link.h */
	struct ifla_vf_broadcast {
		__u8 broadcast[32];
	};

The function then copies dev->broadcast into it using dev->addr_len
as the length:

	memcpy(vf_broadcast.broadcast, dev->broadcast, dev->addr_len);

On Ethernet devices (the overwhelming majority of SR-IOV NICs)
dev->addr_len is 6, so only the first 6 bytes of broadcast[] are
written. The remaining 26 bytes retain whatever was previously on
the kernel stack. The full struct is then handed to userspace via:

	nla_put(skb, IFLA_VF_BROADCAST,
		sizeof(vf_broadcast), &vf_broadcast)

leaking up to 26 bytes of uninitialised kernel stack per VF per
RTM_GETLINK request, repeatable.

The other vf_* structs in the same function are explicitly zeroed
for exactly this reason - see the memset() calls for ivi,
vf_vlan_info, node_guid and port_guid a few lines above.
vf_broadcast was simply missed when it was added.

Reachability: any unprivileged local process can open AF_NETLINK /
NETLINK_ROUTE without capabilities and send RTM_GETLINK with an
IFLA_EXT_MASK attribute carrying RTEXT_FILTER_VF. The kernel walks
each VF and emits IFLA_VF_BROADCAST, leaking 26 bytes of stack per
VF per request. Stack residue at this call site can include return
addresses and transient sensitive data; KASAN with stack
instrumentation, or KMSAN, will flag the nla_put() when reproduced.

Zero the on-stack struct before the partial memcpy, matching the
existing pattern used for the other vf_* structs in the same
function.

Fixes: 75345f888f70 ("ipoib: show VF broadcast address")
Cc: stable@vger.kernel.org
Signed-off-by: Kai Zen <kai.aizen.dev@gmail.com>
Link: https://patch.msgid.link/3c506e8f936e52b57620269b55c348af05d413a2.1777557228.git.kai.aizen.dev@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The stack-allocated `struct ifla_vf_broadcast vf_broadcast` was not zeroed before a partial `memcpy` that only copied the first `dev->addr_len` bytes (typically 6 for Ethernet) into the 32‑byte `broadcast` field. The remaining 26 bytes retained uninitialized kernel stack data, which were then leaked to userspace via `nla_put()`.

Here is the patch:

 static noinline_for_stack int rtnl_fill_vfinfo(struct sk_buff *skb,
 					       struct net_device *dev,
 					       int vfs_num,
 					       u32 ext_filter_mask)
 {
 	struct ifla_vf_rss_query_en vf_rss_query_en;
 	struct nlattr *vf, *vfstats, *vfvlanlist;
 	struct ifla_vf_link_state vf_linkstate;
 	struct ifla_vf_vlan_info vf_vlan_info;
 	struct ifla_vf_spoofchk vf_spoofchk;
 	struct ifla_vf_tx_rate vf_tx_rate;
 	struct ifla_vf_stats vf_stats;
 	struct ifla_vf_trust vf_trust;
 	struct ifla_vf_vlan vf_vlan;
 	struct ifla_vf_rate vf_rate;
 	struct ifla_vf_mac vf_mac;
 	struct ifla_vf_broadcast vf_broadcast;
 	struct ifla_vf_info ivi;
 	struct ifla_vf_guid node_guid;
 	struct ifla_vf_guid port_guid;

 	memset(&ivi, 0, sizeof(ivi));

 	/* Not all SR-IOV capable drivers support the
 	 * spoofcheck and "RSS query enable" query.  Preset to
 	 * -1 so the user space tool can detect that the driver
 	 * didn't report anything.
 	 */
 	ivi.spoofchk = -1;
 	ivi.rss_query_en = -1;
 	ivi.trusted = -1;
 	/* The default value for VF link state is "auto"
 	 * IFLA_VF_LINK_STATE_AUTO which equals zero
 	 */
 	ivi.linkstate = 0;
 	/* VLAN Protocol by default is 802.1Q */
 	ivi.vlan_proto = htons(ETH_P_8021Q);
 	if (dev->netdev_ops->ndo_get_vf_config(dev, vfs_num, &ivi))
 		return 0;

 	memset(&vf_vlan_info, 0, sizeof(vf_vlan_info));
 	memset(&node_guid, 0, sizeof(node_guid));
 	memset(&port_guid, 0, sizeof(port_guid));

 	vf_mac.vf =
 		vf_vlan.vf =
 		vf_vlan_info.vf =
 		vf_rate.vf =
 		vf_tx_rate.vf =
 		vf_spoofchk.vf =
 		vf_linkstate.vf =
 		vf_rss_query_en.vf =
 		vf_trust.vf =
 		node_guid.vf =
 		port_guid.vf = ivi.vf;

 	memcpy(vf_mac.mac, ivi.mac, sizeof(ivi.mac));
+	memset(&vf_broadcast, 0, sizeof(vf_broadcast));
 	memcpy(vf_broadcast.broadcast, dev->broadcast, dev->addr_len);
 	vf_vlan.vlan = ivi.vlan;
 	vf_vlan.qos = ivi.qos;
 	vf_vlan_info.vlan = ivi.vlan;
 	vf_vlan_info.qos = ivi.qos;
 	vf_vlan_info.vlan_proto = ivi.vlan_proto;
 	vf_tx_rate.rate = ivi.max_tx_rate;
 	vf_rate.min_tx_rate = ivi.min_tx_rate;
 	vf_rate.max_tx_rate = ivi.max_tx_rate;
 	vf_spoofchk.setting = ivi.spoofchk;
 	vf_linkstate.link_state = ivi.linkstate;
 	vf_rss_query_en.setting = ivi.rss_query_en;
 	vf_trust.setting = ivi.trusted;
 	vf = nla_nest_start_noflag(skb, IFLA_VF_INFO);
 	if (!vf)
 		return -EMSGSIZE;
 	if (nla_put(skb, IFLA_VF_MAC, sizeof(vf_mac), &vf_mac) ||
 	    nla_put(skb, IFLA_VF_BROADCAST, sizeof(vf_broadcast), &vf_broadcast) ||
 	    nla_put(skb, IFLA_VF_VLAN, sizeof(vf_vlan), &vf_vlan) ||
 	    nla_put(skb, IFLA_VF_RATE, sizeof(vf_rate),
 		    &vf_rate) ||
 	    nla_put(skb, IFLA_VF_TX_RATE, sizeof(vf_tx_rate),
 		    &vf_tx_rate) ||
 	    nla_put(skb, IFLA_VF_SPOOFCHK, sizeof(vf_spoofchk),
 		    &vf_spoofchk) ||
 	    nla_put(skb, IFLA_VF_LINK_STATE, sizeof(vf_linkstate),
 		    &vf_linkstate) ||
 	    nla_put(skb, IFLA_VF_RSS_QUERY_EN,
 		    sizeof(vf_rss_query_en),
 		    &vf_rss_query_en) ||
 	    nla_put(skb, IFLA_VF_TRUST,
 		    sizeof(vf_trust), &vf_trust))
 		goto nla_put_vf_failure;

 	if (dev->netdev_ops->ndo_get_vf_guid &&
 	    !dev->netdev_ops->ndo_get_vf_guid(dev, vfs_num, &node_guid,
 					      &port_guid)) {
 		if (nla_put(skb, IFLA_VF_IB_NODE_GUID, sizeof(node_guid),
 			    &node_guid) ||
 		    nla_put(skb, IFLA_VF_IB_PORT_GUID, sizeof(port_guid),
 			    &port_guid))
 			goto nla_put_vf_failure;
 	}
 	vfvlanlist = nla_nest_start_noflag(skb, IFLA_VF_VLAN_LIST);
 	if (!vfvlanlist)
 		goto nla_put_vf_failure;
 	if (nla_put(skb, IFLA_VF_VLAN_INFO, sizeof(vf_vlan_info),
 		    &vf_vlan_info)) {
 		nla_nest_cancel(skb, vfvlanlist);
 		goto nla_put_vf_failure;
 	}
 	nla_nest_end(skb, vfvlanlist);
 	if (~ext_filter_mask & RTEXT_FILTER_SKIP_STATS) {
 		memset(&vf_stats, 0, sizeof(vf_stats));
 		if (dev->netdev_ops->ndo_get_vf_stats)
 			dev->netdev_ops->ndo_get_vf_stats(dev, vfs_num,
 							  &vf_stats);
 		vfstats = nla_nest_start_noflag(skb, IFLA_VF_STATS);
 		if (!vfstats)
 			goto nla_put_vf_failure;
 		if (nla_put_u64_64bit(skb, IFLA_VF_STATS_RX_PACKETS,
 				      vf_stats.rx_packets, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_TX_PACKETS,
 				      vf_stats.tx_packets, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_RX_BYTES,
 				      vf_stats.rx_bytes, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_TX_BYTES,
 				      vf_stats.tx_bytes, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_BROADCAST,
 				      vf_stats.broadcast, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_MULTICAST,
 				      vf_stats.multicast, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_RX_DROPPED,
 				      vf_stats.rx_dropped, IFLA_VF_STATS_PAD) ||
 		    nla_put_u64_64bit(skb, IFLA_VF_STATS_TX_DROPPED,
 				      vf_stats.tx_dropped, IFLA_VF_STATS_PAD)) {
 			nla_nest_cancel(skb, vfstats);
 			goto nla_put_vf_failure;
 		}
 		nla_nest_end(skb, vfstats);
 	}
 	nla_nest_end(skb, vf);
 	return 0;

 nla_put_vf_failure:
 	nla_nest_cancel(skb, vf);
 	return -EMSGSIZE;
 }



